import parse
import re

# Reproduce the exact failing format
fmt = '''
letters: {:w}
non-letters: {:W}
whitespace: \"{\"{:s}\"\"}\"
non-whitespace: \t{:S}\n
digits: {:d}
non-digits: {:D}
numbers with thousands: {:n}
fixed-point: {:f}
floating-point: {:e}
general numbers: {:g} {:g}
binary: {:b}
octal: {:o}
hex: {:x}
ISO 8601 e.g. {:ti}
RFC2822 e.g. {:te}
Global e.g. {:tg}
US e.g. {:ta}
ctime() e.g. {:tc}
HTTP e.g. {:th}
time: {:tt}
final value: {}
'''

p = parse.Parser(fmt)

# Count groups before 'general numbers' in the expression
expr = p._match_re.pattern
idx = expr.find('general numbers')
before = expr[:idx]

# Count capture groups (excluding non-capturing)
# Remove named groups
temp = re.sub(r'\(\?P<[^>]+>', '(', before)
# Remove non-capturing groups (?:(...))
temp = re.sub(r'\((?:)', '', temp)
# Remove escaped parens \( and \)
temp = re.sub(r'\\[()]', '', temp)
# Now count remaining '('
count = temp.count('(')
print('Capture groups before general numbers:', count)

# Also check what groups are at indices 8, 9, 10, 11, 12, 13
# These correspond to _fixed_fields positions 7, 8, 9, 10, 11, 12
print('_fixed_fields:', p._fixed_fields)
"
